const express = require('express');
const router = express.Router();
const store = new Map();

router.get('/{{resource}}', (req, res) => res.json([...store.values()]));
router.get('/{{resource}}/:{{id_field}}', (req, res) => {
  const item = store.get(req.params.{{id_field}});
  if (!item) return res.status(404).json({ error: 'not found' });
  res.json(item);
});
router.post('/{{resource}}', (req, res) => {
  const id = String(Date.now());
  const item = { {{id_field}}: id, ...req.body };
  store.set(id, item);
  res.status(201).json(item);
});
router.put('/{{resource}}/:{{id_field}}', (req, res) => {
  if (!store.has(req.params.{{id_field}})) return res.status(404).end();
  const updated = { ...store.get(req.params.{{id_field}}), ...req.body };
  store.set(req.params.{{id_field}}, updated);
  res.json(updated);
});
router.delete('/{{resource}}/:{{id_field}}', (req, res) => {
  store.delete(req.params.{{id_field}});
  res.status(204).end();
});

module.exports = router;
